INSERT_SQL = """
INSERT OR IGNORE INTO dim_exercises (
    name,
    description,
    instructions,
    primary_muscle,
    secondary_muscles,
    pattern,
    equipment,
    mechanic,
    level,
    intensity,
    tracking_type,
    is_unilateral,
    media_url,
    icon_url,
    anatomy_diagram_url,
    is_custom
) VALUES (
    ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?,
    NULL, -- media_url
    NULL, -- icon_url
    NULL, -- anatomy_diagram_url
    0     -- is_custom (0 = default app exercise)
);
"""

def seed_150_plus_exercises(db_path: str = DB_FILENAME) -> None:
    """Seeds dim_exercises with 165 exercises and sets all media columns to NULL."""
    path = Path(db_path)
    if not path.exists():
        print(f"Error: Database '{db_path}' not found. Run init_db.py first!")
        return

    # Convert secondary_muscles list into a JSON string for SQLite
    formatted_rows = [
        (
            name, desc, instr, p_muscle, json.dumps(s_muscles),
            pattern, equip, mech, level, intensity, track, unilateral
        )
        for (
            name, desc, instr, p_muscle, s_muscles,
            pattern, equip, mech, level, intensity, track, unilateral
        ) in RAW_EXERCISES
    ]

    try:
        with sqlite3.connect(path) as conn:
            conn.execute("PRAGMA foreign_keys = ON;")
            cursor = conn.cursor()

            cursor.executemany(INSERT_SQL, formatted_rows)
            conn.commit()

            cursor.execute("SELECT COUNT(*) FROM dim_exercises;")
            total = cursor.fetchone()[0]
            print(f"Successfully seeded database! Total exercises in 'dim_exercises': {total}\n")

            cursor.execute("""
                SELECT primary_muscle, COUNT(*) 
                FROM dim_exercises 
                GROUP BY primary_muscle 
                ORDER BY COUNT(*) DESC;
            """)
            print("Exercise count by primary muscle group:")
            for muscle, count in cursor.fetchall():
                print(f"  - {muscle.capitalize():<12}: {count}")

    except sqlite3.Error as e:
        print(f"SQLite error occurred: {e}")

if __name__ == "__main__":
    seed_150_plus_exercises()